CREATE TABLE usage_rows (key text PRIMARY KEY, seq bigserial NOT NULL UNIQUE, at timestamptz NOT NULL, host text NOT NULL, source text, repo text, issue integer, step text, provider text, model text, json text NOT NULL, sender text NOT NULL);
CREATE INDEX usage_rows_at ON usage_rows (at);
CREATE INDEX usage_rows_repo_step ON usage_rows (repo, step);
CREATE INDEX usage_rows_repo_issue ON usage_rows (repo, issue, at);
CREATE TABLE usage_limit_rows (key text PRIMARY KEY, at timestamptz NOT NULL, host text NOT NULL, source text, provider text, "limit" text, json text NOT NULL, sender text NOT NULL);
CREATE INDEX usage_limit_rows_at ON usage_limit_rows (at);
CREATE TABLE usage_import_positions (file text PRIMARY KEY, position bigint NOT NULL, updated_at timestamptz NOT NULL);

CREATE TABLE job_commands (id text PRIMARY KEY, seq bigserial NOT NULL UNIQUE, repo text NOT NULL, issue integer NOT NULL, kind text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, target_host text NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'acked', 'done', 'failed')), created_at timestamptz NOT NULL DEFAULT now(), acked_at timestamptz, result jsonb);
CREATE INDEX job_commands_open ON job_commands (target_host, seq) WHERE status IN ('queued', 'acked');
CREATE INDEX job_commands_issue ON job_commands (repo, issue);

CREATE TABLE hosts (host text PRIMARY KEY, revision text, cli_versions jsonb, load jsonb, busy boolean NOT NULL DEFAULT false, implementing integer, publishing integer, heartbeat_at timestamptz NOT NULL, capabilities jsonb);
CREATE TABLE notices (id bigserial PRIMARY KEY, host text NOT NULL, kind text NOT NULL, data jsonb NOT NULL, at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notices_at ON notices (at);

CREATE TABLE jobs (id bigserial PRIMARY KEY, repo text NOT NULL, issue integer NOT NULL CHECK (issue > 0), title text NOT NULL DEFAULT '', kind text NOT NULL DEFAULT 'normal' CHECK (kind IN ('normal', 'followup', 'investigation', 'stall_fix')), priority smallint NOT NULL DEFAULT 0 CHECK (priority IN (0, 1)), filed_at timestamptz NOT NULL DEFAULT now(), scope text[] NOT NULL DEFAULT ARRAY['*'], scope_source text NOT NULL DEFAULT 'estimated' CHECK (scope_source IN ('declared', 'estimated', 'widened')), provider text, tier text, status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'held', 'failed', 'stopped', 'merged', 'closed')), hold_reason text CHECK (hold_reason IN ('review_held', 'question', 'deletions', 'scope_wait')), generation integer NOT NULL DEFAULT 0, branch text, pr integer, head_sha text, lease_host text, lease_epoch integer NOT NULL DEFAULT 0, lease_expires_at timestamptz, progress_at timestamptz, view jsonb NOT NULL DEFAULT '{}'::jsonb, result jsonb, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (repo, issue), CHECK ((status = 'held') = (hold_reason IS NOT NULL)));
CREATE INDEX jobs_queue ON jobs (repo, priority DESC, filed_at) WHERE status = 'queued';
CREATE INDEX jobs_running ON jobs (lease_host) WHERE status = 'running';
CREATE TABLE job_deps (job_id bigint NOT NULL REFERENCES jobs (id) ON DELETE CASCADE, depends_on bigint NOT NULL REFERENCES jobs (id) ON DELETE CASCADE, PRIMARY KEY (job_id, depends_on), CHECK (job_id <> depends_on));
CREATE INDEX job_deps_depends_on ON job_deps (depends_on);
CREATE TABLE merge_turns (repo text PRIMARY KEY, holder_host text, job_id bigint REFERENCES jobs (id) ON DELETE SET NULL, request_id text, epoch integer NOT NULL DEFAULT 0, expires_at timestamptz);
CREATE TABLE job_events (seq bigserial PRIMARY KEY, job_id bigint NOT NULL REFERENCES jobs (id) ON DELETE CASCADE, host text, kind text NOT NULL, at timestamptz NOT NULL DEFAULT now(), data jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX job_events_job ON job_events (job_id, seq);
CREATE TABLE repo_notes (id bigserial PRIMARY KEY, repo text NOT NULL, kind text NOT NULL CHECK (kind IN ('finding', 'followup', 'improvement')), job_id bigint REFERENCES jobs (id) ON DELETE SET NULL, at timestamptz NOT NULL DEFAULT now(), data jsonb NOT NULL);
CREATE INDEX repo_notes_repo ON repo_notes (repo, kind, at);
ALTER TABLE hosts ADD COLUMN drain jsonb, ADD COLUMN checks jsonb, ADD COLUMN ready boolean NOT NULL DEFAULT false, ADD COLUMN image_revision text, ADD COLUMN capacity integer;

CREATE TABLE releases (host text NOT NULL, flavor text NOT NULL CHECK (flavor IN ('', '-python')), registry text NOT NULL, tag text NOT NULL, digest text NOT NULL, revision text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (host, flavor));
CREATE TABLE host_image_tokens (host text PRIMARY KEY, hash text NOT NULL UNIQUE, issued_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE host_image_results (host text NOT NULL, tag text NOT NULL, flavor text NOT NULL, digest text NOT NULL, status text NOT NULL CHECK (status IN ('success', 'failed')), at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (host, tag, flavor));

CREATE TABLE app_deploy_heads (repo text PRIMARY KEY, commit_sha text NOT NULL, deploy_host text NOT NULL);
CREATE TABLE app_deployments (id bigserial PRIMARY KEY, repo text NOT NULL, commit_sha text NOT NULL CHECK (commit_sha ~ '^[a-f0-9]{40}$'), deploy_host text NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','deployed','rolled_back','failed')), result jsonb, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz, UNIQUE (repo, commit_sha));
CREATE INDEX app_deployments_queue ON app_deployments (deploy_host, status, id);

ALTER TABLE releases ADD COLUMN kind text NOT NULL DEFAULT 'align' CHECK (kind IN ('align','soon','lazy'));
CREATE TABLE client_release_history (host text NOT NULL, flavor text NOT NULL, revision text NOT NULL, base_revision text, kind text NOT NULL CHECK (kind IN ('align','soon','lazy')), changed_files jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (host, flavor, revision));
INSERT INTO client_release_history (host, flavor, revision, kind) SELECT host, flavor, revision, 'align' FROM releases;

-- Collect only when jobs.Store enables transaction-local publication.
CREATE FUNCTION capture_job_list_change() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  changes text := current_setting('issue_desk.job_changes', true);
  target_id bigint;
  target jsonb;
BEGIN
  IF changes IS NULL OR changes = '' THEN
    RETURN NULL;
  END IF;
  IF TG_TABLE_NAME = 'jobs' THEN
    IF TG_OP = 'UPDATE' AND
      ROW(NEW.repo, NEW.issue, NEW.title, NEW.kind, NEW.priority, NEW.filed_at,
          NEW.scope, NEW.scope_source, NEW.provider, NEW.tier, NEW.status,
          NEW.hold_reason, NEW.generation, NEW.branch, NEW.pr, NEW.head_sha,
          NEW.lease_host, NEW.view - 'progress', NULLIF(NEW.result, 'null'::jsonb))
      IS NOT DISTINCT FROM
      ROW(OLD.repo, OLD.issue, OLD.title, OLD.kind, OLD.priority, OLD.filed_at,
          OLD.scope, OLD.scope_source, OLD.provider, OLD.tier, OLD.status,
          OLD.hold_reason, OLD.generation, OLD.branch, OLD.pr, OLD.head_sha,
          OLD.lease_host, OLD.view - 'progress', NULLIF(OLD.result, 'null'::jsonb)) THEN
      RETURN NULL;
    END IF;
    IF TG_OP = 'DELETE' THEN
      target_id := OLD.id;
      target := jsonb_build_object('project', OLD.repo, 'number', OLD.issue);
    ELSE
      target_id := NEW.id;
      target := jsonb_build_object('project', NEW.repo, 'number', NEW.issue);
    END IF;
  ELSE
    IF TG_TABLE_NAME = 'job_events' THEN
      -- These events contribute to issueapi.dispatchProjection in list rows.
      IF NEW.kind NOT IN ('dispatch_skip','scope_reserved','handed_back','leased','requeued') THEN
        RETURN NULL;
      END IF;
      IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN
        RETURN NULL;
      END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN target_id := OLD.job_id;
    ELSE target_id := NEW.job_id;
    END IF;
    SELECT jsonb_build_object('project', repo, 'number', issue) INTO target FROM jobs WHERE id=target_id;
  END IF;
  IF target IS NOT NULL THEN
    PERFORM set_config('issue_desk.job_changes',
      (changes::jsonb || jsonb_build_object(target_id::text, target))::text, true);
  END IF;
  RETURN NULL;
END;
$$;
CREATE TRIGGER jobs_list_change AFTER INSERT OR UPDATE OR DELETE ON jobs FOR EACH ROW EXECUTE FUNCTION capture_job_list_change();
CREATE TRIGGER job_deps_list_change AFTER INSERT OR DELETE ON job_deps FOR EACH ROW EXECUTE FUNCTION capture_job_list_change();
CREATE TRIGGER job_events_list_change AFTER INSERT OR UPDATE ON job_events FOR EACH ROW EXECUTE FUNCTION capture_job_list_change();

ALTER TABLE job_deps ADD COLUMN wait_started_at timestamptz, ADD COLUMN wait_unknown boolean NOT NULL DEFAULT false;
ALTER TABLE job_deps ADD CONSTRAINT job_deps_wait_consistent CHECK (NOT (wait_unknown AND wait_started_at IS NOT NULL));
CREATE FUNCTION dependency_waiting(edge_job bigint, edge_predecessor bigint) RETURNS boolean LANGUAGE sql VOLATILE AS $$
 SELECT COALESCE((SELECT j.status='queued' AND NOT (COALESCE((p.status='merged' OR (p.status='closed' AND (
 (jsonb_typeof(j.view->'acceptanceTransferWait'->'ownedTargets')='object' AND (j.view->'acceptanceTransferWait'->'ownedTargets') ? p.id::text)
 OR (jsonb_typeof(j.view->'dependencyMerges'->(p.id::text))='object'
 AND jsonb_typeof(j.view->'dependencyMerges'->(p.id::text)->'pr')='number'
 AND (j.view->'dependencyMerges'->(p.id::text)->>'pr') ~ '^[1-9][0-9]*$'
 AND jsonb_typeof(j.view->'dependencyMerges'->(p.id::text)->'mergeCommit')='string'
 AND (j.view->'dependencyMerges'->(p.id::text)->>'mergeCommit') ~ '^[a-f0-9]{40}$')
 OR (jsonb_typeof(j.view->'dependencyRelations'->(p.id::text))='object'
 AND j.view->'dependencyRelations'->(p.id::text)->>'relation'='unrelated'
 AND jsonb_typeof(j.view->'dependencyRelations'->(p.id::text)->'evidence')='string'
 AND btrim(j.view->'dependencyRelations'->(p.id::text)->>'evidence')<>'')))), false)) FROM jobs j JOIN jobs p ON p.id=edge_predecessor WHERE j.id=edge_job), false)
$$;
UPDATE job_deps d SET wait_unknown=true WHERE dependency_waiting(d.job_id,d.depends_on);
CREATE FUNCTION dependency_wait_edge() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 PERFORM id FROM jobs WHERE id IN (NEW.job_id, NEW.depends_on) ORDER BY id FOR SHARE;
 IF dependency_waiting(NEW.job_id,NEW.depends_on) THEN
   NEW.wait_started_at := clock_timestamp(); NEW.wait_unknown := false;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER dependency_wait_edge_insert BEFORE INSERT ON job_deps FOR EACH ROW EXECUTE FUNCTION dependency_wait_edge();
CREATE FUNCTION dependency_wait_job() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 UPDATE job_deps d SET
   wait_started_at = CASE WHEN dependency_waiting(d.job_id,d.depends_on) THEN COALESCE(d.wait_started_at, CASE WHEN NOT d.wait_unknown THEN clock_timestamp() END) ELSE NULL END,
   wait_unknown = CASE WHEN dependency_waiting(d.job_id,d.depends_on) THEN d.wait_unknown ELSE false END
 WHERE d.job_id=NEW.id OR d.depends_on=NEW.id;
 RETURN NULL;
END $$;
CREATE TRIGGER dependency_wait_job_update AFTER UPDATE OF status, view ON jobs FOR EACH ROW
 WHEN (OLD.status IS DISTINCT FROM NEW.status OR OLD.view IS DISTINCT FROM NEW.view)
 EXECUTE FUNCTION dependency_wait_job();

